WITH product_stats AS (SELECT product_id, SUM(unit_price * quantity) AS revenue, ROUND(AVG(unit_price), 2) AS avg_unit_price FROM order_items WHERE unit_price <= 230 GROUP BY product_id) SELECT p.id, p.product_name, ps.revenue, ps.avg_unit_price FROM products p INNER JOIN product_stats ps ON p.id = ps.product_id ORDER BY product_name
